#!/bin/bash
HASH=$(git rev-parse --short HEAD 2>/dev/null || echo "unknown")
STATUS=$(git status --short 2>/dev/null)
DIRTY="clean"
if [ -n "$STATUS" ]; then
    DIRTY="dirty"
fi

cat << SWIFT > Sources/NativeHACore/GeneratedVersion.swift
// This file is generated by tools/generate_version.sh
public enum AppVersion {
    public static let gitHash = "$HASH"
    public static let gitDirty = "$DIRTY"
}
SWIFT
